 function sourcesView(){
  $('source-overview').innerHTML=`<section class="panel scope-explainer"><h2>色の付いた範囲と円の読み方</h2><p>青い破線は駅の位置を含む約500m統計区画の外枠です。公表値は都県別の成分で、区画全体を一つの実測範囲と確定したものではありません。商業中心地の境界や駅からの半径を示していません。</p><p>地図の数量円は同じ区画で1つ、路線数は同じ駅群で1つ。数の4倍は円の面積4倍になります。学生の住民比は色で0〜100%を表示します。絞り込みで凡例の基準は変わりません。</p><p>プロフィールの中央値は、対象内の同一区画（路線数では同一駅群）を重複除去し、比較できる公表値だけで算定します。「数値あり」の分母は対象区画・駅群の全数です。同規模の街との比較、中心地面積・密度・街間距離は未算定です。</p></section><div class="source-cards"><article class="panel"><span class="eyebrow">01 / GEOGRAPHY</span><h2>どこの数字か</h2><p>駅のある約500mの統計区画、商業集積地区、自治体では、集計範囲が異なります。</p><p class="note">区画を駅中心の半径500m圏や繁華街全体と読み替えません。</p></article><article class="panel"><span class="eyebrow">02 / TIME</span><h2>いつの数字か</h2><p>指標ごとに年次を表示します。売上は2020年、商業構造は2021年です。</p><p class="note">現在の店舗や学生の数を表すものではありません。</p></article><article class="panel"><span class="eyebrow">03 / AVAILABILITY</span><h2>「—」は0ではない</h2><p>未取得・秘匿・合算・都県境の値は、比較から除外し、理由を示します。</p><p class="note">数値ありの件数は、統計自体の精度を評価した点数ではありません。</p></article></div><section class="panel"><h2>指標の定義</h2><div class="table-wrap"><table class="source-table"><thead><tr><th>指標</th><th>単位・年</th><th>対象範囲</th><th>読み方・公式出典</th></tr></thead><tbody>${Object.entries(METRIC_DETAILS).map(([k,m])=>`<tr id="def-${k}"><th>${m.label}<small>${m.kind}</small></th><td>${m.unit}<br>${m.year}</td><td>${m.scope}</td><td>${m.note}<br>${sourceLink(SOURCES[m.source])}</td></tr>`).join('')}</tbody></table></div></section>`;
 }
