  const outline=state.outline&&selected?scopeOutline(data,selected):{type:'FeatureCollection',features:[]};map.getSource('selected-scope')?.setData(outline);$('scope-note').hidden=!outline.features.length;$('scope-note').textContent=outline.features.length?`統計区画 ${selected.meshCode} の外枠。公表値は都県別で、塗った土地全体の実測値や商業中心地の境界ではありません。${outline.features[0].properties.partitioned?' 都県部分の境界は未確定のため、比較値を合算しません。':''}`:'';
